H.background();
const f = Math.max(P.f, 0.1);
const lam = Math.max(P.lam, 0.2);
const v = f * lam;
const A = 0.7;
const kw = (2 * Math.PI) / lam;
const w = 2 * Math.PI * f;
H.text("Wave on a string: v = f λ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Speed = frequency × wavelength; the crest travels right at v", 24, 52, { color: H.colors.sub, size: 13 });
const xMax = 4;
const view = H.plot2d({ xMin: 0, xMax: xMax, yMin: -1.2, yMax: 1.2 });
view.axes();
view.fn(x => A * Math.sin(kw * x - w * t), { color: H.colors.accent, width: 2 });
let xc = (Math.PI / 2 + w * t) / kw;
xc = xc % lam;
view.dot(xc, A, { r: 6, fill: H.colors.warn });
view.line(0, -1.05, lam, -1.05, { color: H.colors.violet, width: 2 });
view.text("λ = " + lam.toFixed(2) + " m", lam * 0.5, -1.18, { color: H.colors.violet, size: 12 });
H.text("f = " + f.toFixed(2) + " Hz   λ = " + lam.toFixed(2) + " m", 24, 76, { color: H.colors.sub, size: 13 });
H.text("v = f λ = " + v.toFixed(2) + " m/s", 24, 96, { color: H.colors.accent2, size: 13 });
